  "Nice–Cannes":{lat:43.6949,lon:7.2674,mon:11,day:4},
  "Barcelona":{lat:41.3886,lon:2.1694,mon:3,day:10},
  "San Sebastián":{lat:43.3207,lon:-1.9842,mon:11,day:26}
