// Local hours over which the mass field is on course (used to average weather).
const RACE_WINDOW = { start: 8, end: 13 };
// A race within this many days ahead uses the live forecast; otherwise we use
// A race within this many days ahead uses the live forecast. Once a race is
// more than POST_RACE_GRACE_DAYS past, we point the display at next year's
// edition but still source the temperature from the most recent running.
const FORECAST_WINDOW_DAYS = 14;
const POST_RACE_GRACE_DAYS = 30;

// Effective running temperature: what the heat feels like to a working runner.
// air temp + solar load + a humidity penalty (only bites when warm) - wind cooling.
// Coefficients are deliberately simple and tunable.
function effectiveRunningTemp(w) {
  const solarTerm    = (w.solarWm2 / 1000) * 4;                                 // up to ~+4°C in full midday sun
  const humidityTerm = Math.max(0, w.rh - 50) / 50 * Math.max(0, w.airTempC - 12) * 0.35;
  const windTerm     = Math.min(Math.max(w.windKmh, 0), 25) * 0.10;             // up to ~-2.5°C cooling
  return w.airTempC + solarTerm + humidityTerm - windTerm;
}

function round1(x) { return Math.round(x * 10) / 10; }

const MONTHS = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
function fmtDate(iso) { const p = iso.split("-"); return `${parseInt(p[2],10)} ${MONTHS[parseInt(p[1],10)-1]} ${p[0]}`; }

// Resolve, relative to `now`, the date we DISPLAY (the next time this race is
// run) and the date we pull WEATHER from (the most recent actual running, or a
// live forecast if the race is imminent). These can differ — e.g. a month after
// Boston 2026 we show "next race ~Apr 2027" but use the real 2026 race-day temp.
//   returns { weatherDate, weatherMode: "forecast"|"archive", displayDate }
function resolveRaceDate(c, now) {
  const MS = 86400000;
  const y = now.getUTCFullYear();
  const pad = (n) => String(n).padStart(2, "0");
  const iso = (yy) => `${yy}-${pad(c.mon)}-${pad(c.day)}`;
  const daysUntil = Math.round((Date.UTC(y, c.mon - 1, c.day) - now.getTime()) / MS);

  if (daysUntil >= 0) {
    // Upcoming this year
    if (daysUntil <= FORECAST_WINDOW_DAYS) return { weatherDate: iso(y), weatherMode: "forecast", displayDate: iso(y) };
    return { weatherDate: iso(y - 1), weatherMode: "archive", displayDate: iso(y) };   // estimate from last running
  }
  // Already happened this year
  const daysSince = -daysUntil;
  if (daysSince <= POST_RACE_GRACE_DAYS) return { weatherDate: iso(y), weatherMode: "archive", displayDate: iso(y) };  // just ran
  return { weatherDate: iso(y), weatherMode: "archive", displayDate: iso(y + 1) };     // long past -> next year's edition, this year's temp
}

// Fetch ONE specific day's hourly weather (forecast or archive) and reduce the
// race-window hours to that day's averages. No multi-year averaging.
//   forecast: https://api.open-meteo.com/v1/forecast?...&start_date=D&end_date=D
//   archive:  https://archive-api.open-meteo.com/v1/archive?...&start_date=D&end_date=D
//   hourly=temperature_2m,relative_humidity_2m,wind_speed_10m,shortwave_radiation&timezone=auto
async function fetchRaceDayConditions(c, now) {
  const r = resolveRaceDate(c, now || new Date());
  const base = r.weatherMode === "forecast"
    ? "https://api.open-meteo.com/v1/forecast"
    : "https://archive-api.open-meteo.com/v1/archive";
  const u = base +
    `?latitude=${c.lat}&longitude=${c.lon}&start_date=${r.weatherDate}&end_date=${r.weatherDate}` +
    "&hourly=temperature_2m,relative_humidity_2m,wind_speed_10m,shortwave_radiation&timezone=auto";
  let d = null;
  try { const res = await fetch(u); d = res.ok ? await res.json() : null; } catch { d = null; }
  if (!d || !d.hourly || !Array.isArray(d.hourly.time)) return null;
  const H = d.hourly;
  let t = 0, rh = 0, wind = 0, solar = 0, n = 0;
  for (let i = 0; i < H.time.length; i++) {
    const hr = parseInt(String(H.time[i]).slice(11, 13), 10);
    if (hr < RACE_WINDOW.start || hr > RACE_WINDOW.end) continue;
    const ta = H.temperature_2m && H.temperature_2m[i];
    if (ta == null) continue;
    const rhv = H.relative_humidity_2m && H.relative_humidity_2m[i];
    const wv  = H.wind_speed_10m && H.wind_speed_10m[i];
    const sv  = H.shortwave_radiation && H.shortwave_radiation[i];
    t += ta; rh += (rhv == null ? 60 : rhv); wind += (wv == null ? 5 : wv); solar += (sv == null ? 0 : sv); n++;
  }
  if (n === 0) return null;
  return { airTempC: t / n, rh: rh / n, windKmh: wind / n, solarWm2: solar / n,
           weatherDate: r.weatherDate, displayDate: r.displayDate, mode: r.weatherMode, samples: n };
}

function conditionsSummary(w) {
  const t = Math.round(w.airTempC);
  const wind = w.windKmh < 8 ? "light wind" : (w.windKmh < 18 ? "moderate wind" : "windy");
  const tail = `${t}°C, ${Math.round(w.rh)}% humidity, ${wind}`;
  if (w.mode === "forecast") return `Forecast for ${fmtDate(w.displayDate)}: ${tail}`;
  const sameYear = w.displayDate.slice(0, 4) === w.weatherDate.slice(0, 4);
  if (sameYear) return `Race day ${fmtDate(w.weatherDate)}: ${tail}`;
  return `Next race ~${fmtDate(w.displayDate)} · from ${w.weatherDate.slice(0, 4)} race: ${tail}`;
}

// ====== ENTITLEMENT CONFIG — CONFIRM AGAINST YOUR STRIPE PAYMENT LINKS ======
// amount_total is in the smallest currency unit (199 = EUR 1.99, 999 = EUR 9.99).
// Returns "all" or an array of marathon names.
function entitlementFromSession(session) {
  const amount = session.amount_total || 0;
  const ref = (session.client_reference_id || "").trim();
  if (ref === "GPX") return [];                                     // GPX-upload only: no courses (front-end sets its own gpx flag)
  if (amount >= 900) return "all";                                  // bundle / all-access
  if (ref && PAID_NAMES.includes(ref)) return [ref];                // single chosen marathon
  if (amount >= 100) return "all";   // CONFIRM: is your EUR 1.99 link "single" or "all"?
  return [];
}

// ====== SIGNED PASS (stateless, HMAC-SHA256) ======
function b64urlBytes(bytes){ let s=""; for(const b of bytes) s+=String.fromCharCode(b); return btoa(s).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,""); }
function b64urlStr(str){ return btoa(unescape(encodeURIComponent(str))).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,""); }
function unb64urlStr(s){ s=s.replace(/-/g,"+").replace(/_/g,"/"); return decodeURIComponent(escape(atob(s))); }
async function hmac(secret, msg){
  const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(secret), {name:"HMAC",hash:"SHA-256"}, false, ["sign"]);
  const sig = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(msg));
  return b64urlBytes(new Uint8Array(sig));
}
function ctEq(a,b){ if(a.length!==b.length) return false; let r=0; for(let i=0;i<a.length;i++) r|=a.charCodeAt(i)^b.charCodeAt(i); return r===0; }
async function signPass(secret, payloadObj){ const p=b64urlStr(JSON.stringify(payloadObj)); const sig=await hmac(secret,p); return p+"."+sig; }
async function verifyPass(secret, pass){
  if(!secret || !pass || pass.indexOf(".")<0) return null;
  const i=pass.lastIndexOf("."); const p=pass.slice(0,i), sig=pass.slice(i+1);
  const expect=await hmac(secret,p);
  if(!ctEq(sig,expect)) return null;
  let payload;
  try { payload = JSON.parse(unb64urlStr(p)); } catch { return null; }
  if (payload && payload.exp && Date.now() > payload.exp) return null; // sub passes expire; one-time passes don't
  return payload;
}
function grantedNames(unlocked){ return unlocked==="all" ? PAID_NAMES.slice() : (Array.isArray(unlocked)?unlocked:[]); }

// ====== DATA RESPONSE (pure, testable): free columns always, paid only if granted ======
function buildDataResponse(passPayload){
  const out = { distance_km: PLOT_DATA.distance_km, columns: {} };
  for(const n of FREE_NAMES){ const c=COL_BY_NAME[n]; if(PLOT_DATA[c]) out.columns[c]=PLOT_DATA[c]; }
  const unlocked = passPayload ? grantedNames(passPayload.unlocked) : [];
  for(const n of unlocked){ const c=COL_BY_NAME[n]; if(PLOT_DATA[c]) out.columns[c]=PLOT_DATA[c]; }
  out.unlocked = unlocked;
  return out;
}

// ====== Stripe webhook signature (hex HMAC-SHA256 over `${t}.${rawBody}`) ======
async function hmacHex(secret, msg){
  const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(secret), {name:"HMAC",hash:"SHA-256"}, false, ["sign"]);
  const sig = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(msg));
  let hex=""; for(const b of new Uint8Array(sig)) hex += b.toString(16).padStart(2,"0");
  return hex;
}
async function verifyStripeSignature(rawBody, header, secret){
  if(!secret || !header) return false;
  let t=null, v1=null;
  for(const part of header.split(",")){ const eq=part.indexOf("="); if(eq<0) continue; const k=part.slice(0,eq).trim(), v=part.slice(eq+1).trim(); if(k==="t") t=v; if(k==="v1") v1=v; }
  if(!t || !v1) return false;
  const expected = await hmacHex(secret, `${t}.${rawBody}`);
  if(!ctEq(expected, v1)) return false;
  return Math.abs(Date.now()/1000 - Number(t)) < 600; // reject events older than 10 min (replay guard)
}

// ====== Entitlement = one-time grants (permanent) merged with subscription status (live) ======
function subActive(status){ return status === "active" || status === "trialing"; }
function mergeUnlocked(a, b){
  if(a === "all" || b === "all") return "all";
  return Array.from(new Set([...(Array.isArray(a)?a:[]), ...(Array.isArray(b)?b:[])]));
}
async function effectiveEntitlement(env, email){
  let own = [], hasActiveSub = false;
  if(env.ENTITLEMENTS){
    const o = await env.ENTITLEMENTS.get("ent:" + email);
    if(o){ try { own = JSON.parse(o).unlocked || []; } catch {} }
    const s = await env.ENTITLEMENTS.get("subof:" + email);
    if(s){ try { if(subActive(JSON.parse(s).status)) hasActiveSub = true; } catch {} }
  }
  return { unlocked: hasActiveSub ? mergeUnlocked(own, "all") : own, hasActiveSub };
}
async function issuePass(env, email){
  const { unlocked, hasActiveSub } = await effectiveEntitlement(env, email);
  const payload = { unlocked, email, iat: Date.now() };
  if(hasActiveSub) payload.exp = Date.now() + 2*24*60*60*1000; // re-check active subs every ~2 days
  return { pass: await signPass(env.TOKEN_SECRET, payload), unlocked };
}

// ====== Cross-device identity via Strava athlete_id ======
// The Strava athlete_id is stable across a user's devices, so we map
//   athlete:<id> -> { pid (primary), lastPid, email?, at }
// and let any device that connects the same Strava inherit that account's
// entitlements (paid plans / marathons) — phone and laptop see the same thing.
async function accountForAthlete(env, athleteId){
  if(!env.ENTITLEMENTS || !athleteId) return { unlocked: [], pass: null };
  try{
    const araw = await env.ENTITLEMENTS.get("athlete:" + athleteId);
    const a = araw ? (JSON.parse(araw)||{}) : {};
    let email = a.email || null;
    if(!email && a.pid){ const p = await env.ENTITLEMENTS.get("page:" + a.pid); if(p){ email = (JSON.parse(p)||{}).email || null; } }
    if(!email) return { unlocked: [], pass: null };
    const issued = await issuePass(env, email);
    return { unlocked: grantedNames(issued.unlocked), pass: issued.pass };
  }catch(e){ return { unlocked: [], pass: null }; }
}

// Record/refresh the athlete<->pid link on connect, propagate a known email to a
// new device so it unlocks, and return that account's current entitlement.
async function linkStrava(env, pid, athleteId, refreshToken){
  if(!env.ENTITLEMENTS) return { unlocked: [], pass: null };
  const now = Date.now();
  // Preserve the original connect time across token refreshes (used by 24h cleanup).
  let connected_at = now;
  try{ const prev = await env.ENTITLEMENTS.get("strava:" + pid); if(prev){ const pr = JSON.parse(prev)||{}; if(pr.connected_at) connected_at = pr.connected_at; } }catch(e){}
  try{ await env.ENTITLEMENTS.put("strava:" + pid, JSON.stringify({ refresh_token: refreshToken, athlete_id: athleteId, at: now, connected_at })); }catch(e){}

  if(athleteId){
    let email = null;
    try{ const p = await env.ENTITLEMENTS.get("page:" + pid); if(p){ email = (JSON.parse(p)||{}).email || null; } }catch(e){}
    let arec = {};
    try{ const araw = await env.ENTITLEMENTS.get("athlete:" + athleteId); if(araw) arec = JSON.parse(araw)||{}; }catch(e){}
    if(!arec.email && email) arec.email = email;   // first known email wins
    arec.pid = arec.pid || pid;                    // primary pid = first device
    arec.lastPid = pid; arec.at = now;
    try{ await env.ENTITLEMENTS.put("athlete:" + athleteId, JSON.stringify(arec)); }catch(e){}
    // If the athlete already has an email but THIS device's page doesn't, adopt it
    // so this device unlocks the same paid content. Never clobber email recovery.
    if(arec.email && !email && validPid(pid)){
      try{
        const p = await env.ENTITLEMENTS.get("page:" + pid); const rec = p ? (JSON.parse(p)||{}) : {};
        rec.email = arec.email; rec.updated = now;
        await env.ENTITLEMENTS.put("page:" + pid, JSON.stringify(rec));
        const existingPidOf = await env.ENTITLEMENTS.get("pidof:" + arec.email);
        if(!validPid(existingPidOf)) await env.ENTITLEMENTS.put("pidof:" + arec.email, pid);
      }catch(e){}
    }
  }
  return await accountForAthlete(env, athleteId);
}

// ====== 24h auto-revoke for connections that never converted ======
// A person who connects Strava but doesn't purchase within 24h is revoked and
// removed, freeing an athlete slot. Runs from the Cron Trigger (scheduled()).
async function isConverted(env, pid, athleteId){
  try{
    const check = async (email) => {
      if(!email) return false;
      const e = await effectiveEntitlement(env, email);
      return e.hasActiveSub || e.unlocked === "all" || (Array.isArray(e.unlocked) && e.unlocked.length > 0);
    };
    // A purchased plan (Race/Static/Dynamic) always counts as converted.
    if(athleteId){ const pl = await env.ENTITLEMENTS.get("plan:athlete:" + athleteId); if(pl){ const r = JSON.parse(pl)||{}; if(["trialing","active","paid"].indexOf(r.status) >= 0) return true; } }
    if(pid){ const p = await env.ENTITLEMENTS.get("page:" + pid); if(p && await check((JSON.parse(p)||{}).email)) return true; }
    if(athleteId){ const a = await env.ENTITLEMENTS.get("athlete:" + athleteId); if(a && await check((JSON.parse(a)||{}).email)) return true; }
  }catch(e){}
  return false;
}

async function stravaRevokeRefresh(env, refreshToken){
  if(!refreshToken || !env.STRAVA_CLIENT_ID || !env.STRAVA_CLIENT_SECRET) return false;
  try{
    const auth = "Basic " + btoa(env.STRAVA_CLIENT_ID + ":" + env.STRAVA_CLIENT_SECRET);
    const body = "token=" + encodeURIComponent(refreshToken) + "&token_type_hint=refresh_token";
    const r = await fetch("https://www.strava.com/oauth/revoke", { method:"POST", headers:{ "Authorization": auth, "Content-Type":"application/x-www-form-urlencoded" }, body });
    return r.status === 200;   // Strava returns 200 whether or not the token existed
  }catch(e){ return false; }
}

async function cleanupUnconverted(env){
  if(!env.ENTITLEMENTS) return { scanned:0, revoked:0 };
  const TTL = 24*60*60*1000, now = Date.now();
  let cursor, scanned = 0, revoked = 0;
  do{
    const list = await env.ENTITLEMENTS.list({ prefix:"strava:", cursor });
    for(const k of list.keys){
      scanned++;
      try{
        const raw = await env.ENTITLEMENTS.get(k.name); if(!raw) continue;
        const rec = JSON.parse(raw) || {};
        const joined = rec.connected_at || rec.at || 0;
        if(!joined || (now - joined) < TTL) continue;                 // still in grace window
        const pid = k.name.slice("strava:".length);
        if(await isConverted(env, pid, rec.athlete_id)) continue;     // paid -> keep
        await stravaRevokeRefresh(env, rec.refresh_token);            // best-effort revoke
        await env.ENTITLEMENTS.delete(k.name);                        // then forget locally
        if(rec.athlete_id){
          try{ const araw = await env.ENTITLEMENTS.get("athlete:" + rec.athlete_id); if(araw){ const a=JSON.parse(araw)||{}; if(a.pid===pid || a.lastPid===pid) await env.ENTITLEMENTS.delete("athlete:" + rec.athlete_id); } }catch(e){}
        }
        revoked++;
      }catch(e){ /* skip this record, keep going */ }
    }
    cursor = list.list_complete ? undefined : list.cursor;
  } while(cursor);
  return { scanned, revoked };
}

// ====== Plan products (Race / Static / Dynamic) — purchase persisted per identity ======
// Identity is Strava athlete_id when connected, else the buyer's email, so a paid
// plan follows the athlete across devices. Race = one-time; Static/Dynamic =
// subscription with a 14-day trial.
const PLAN_TRIAL_DAYS = 14;
const PLAN_PRODUCTS = ["race", "static", "dynamic"];
const PLAN_PRICE_FALLBACK = {
  RACE:    "price_1U2uf8P4aPbXd2jRFR7pALIp",   // one-time $3.99
  STATIC:  "price_1U2ugYP4aPbXd2jRArWaIfLx",   // recurring $9.99
  DYNAMIC: "price_1U2uhfP4aPbXd2jRgJYQa2JT",   // recurring $19.99
};
function planPrice(env, product){ const p = String(product || "").toUpperCase(); return env["STRIPE_PRICE_" + p] || PLAN_PRICE_FALLBACK[p] || ""; }
async function athleteIdForPid(env, pid){
  if(!pid || !env.ENTITLEMENTS) return 0;
  try{ const s = await env.ENTITLEMENTS.get("strava:" + pid); if(s) return (JSON.parse(s)||{}).athlete_id || 0; }catch(e){}
  return 0;
}
async function grantPlan(env, rec){
  if(!env.ENTITLEMENTS || !rec || PLAN_PRODUCTS.indexOf(rec.product) < 0) return;
  const now = Date.now();
  const val = JSON.stringify({
    product: rec.product, status: rec.status || "active",
    purchased_at: rec.purchased_at || now, trial_ends_at: rec.trial_ends_at || 0,
    sub: rec.sub || null, customer: rec.customer || null,
    email: rec.email || null, athlete_id: rec.athlete_id || 0, updated: now
  });
  if(rec.athlete_id){ try{ await env.ENTITLEMENTS.put("plan:athlete:" + rec.athlete_id, val); }catch(e){} }
  if(rec.email){ try{ await env.ENTITLEMENTS.put("plan:email:" + String(rec.email).toLowerCase(), val); }catch(e){} }
  // Reverse index so a subscription webhook (cancel/renew) can find this identity.
  if(rec.sub){ try{ await env.ENTITLEMENTS.put("plansub:" + rec.sub, JSON.stringify({ athlete_id: rec.athlete_id || 0, email: rec.email || null })); }catch(e){} }
}
// Patch a plan entitlement's status by Stripe subscription id (used by cancel/renew webhooks).
async function setPlanStatusBySub(env, subId, status){
  if(!env.ENTITLEMENTS || !subId) return;
  try{
    const raw = await env.ENTITLEMENTS.get("plansub:" + subId); if(!raw) return;
    const idx = JSON.parse(raw) || {};
    const patch = async (key) => { const r = await env.ENTITLEMENTS.get(key); if(!r) return; const rec = JSON.parse(r) || {}; rec.status = status; rec.updated = Date.now(); await env.ENTITLEMENTS.put(key, JSON.stringify(rec)); };
    if(idx.athlete_id) await patch("plan:athlete:" + idx.athlete_id);
    if(idx.email) await patch("plan:email:" + String(idx.email).toLowerCase());
  }catch(e){}
}
async function getPlan(env, athleteId, email){
  if(!env.ENTITLEMENTS) return null;
  try{
    if(athleteId){ const a = await env.ENTITLEMENTS.get("plan:athlete:" + athleteId); if(a) return JSON.parse(a); }
    if(email){ const e = await env.ENTITLEMENTS.get("plan:email:" + String(email).toLowerCase()); if(e) return JSON.parse(e); }
  }catch(e){}
  return null;
}

// ====== Funnel analytics (Cloudflare D1) ======
// Anonymous pid only. We NEVER store access/refresh tokens, client secrets,
// emails, or activity data here — just event name, pid, timestamp, path,
// marathon slug, and (only for strava_oauth_success) the athlete_id.
// Written solely from user-triggered requests; the cron never calls this.
const ANALYTICS_EVENTS = ["page_open","marathon_selected","connect_strava_clicked","strava_oauth_success","result_viewed","checkout_started","purchase_completed"];
async function logEvent(env, ev){
  if(!env.DB || !ev || !ANALYTICS_EVENTS.includes(ev.name)) return;
  try{
    await env.DB.prepare(
      "INSERT INTO events (ts, name, pid, path, marathon, athlete_id) VALUES (?, ?, ?, ?, ?, ?)"
    ).bind(
      Date.now(),
      ev.name,
      (typeof ev.pid === "string" && ev.pid) ? ev.pid.slice(0,64) : null,
      (typeof ev.path === "string" && ev.path) ? ev.path.slice(0,128) : null,
      (typeof ev.marathon === "string" && ev.marathon) ? ev.marathon.slice(0,64) : null,
      (typeof ev.athlete_id === "number" && ev.athlete_id) ? ev.athlete_id : null
    ).run();
  }catch(e){ /* analytics must never break a request */ }
}

// ====== Stripe webhook handler: keep subscription entitlement current ======
async function handleStripeEvent(evt, env){
  if(!env.ENTITLEMENTS || !evt || !evt.data) return;
  const obj = evt.data.object; if(!obj) return;
  if(evt.type === "checkout.session.completed"){
    // Plan products (race/static/dynamic) — grant the entitlement per identity.
    const md = obj.metadata || {};
    if(md.product && PLAN_PRODUCTS.indexOf(md.product) >= 0){
      const pemail = ((obj.customer_details && obj.customer_details.email) || obj.customer_email || "").toLowerCase() || null;
      const athleteId = (md.athlete_id && Number(md.athlete_id)) || 0;
      const status = md.product === "race" ? "paid" : "trialing";
      await grantPlan(env, { product: md.product, status, sub: obj.subscription || null, customer: obj.customer || null, email: pemail, athlete_id: athleteId });
      return;
    }
    if(obj.mode !== "subscription") return; // one-time purchases handled by /verify
    const email = ((obj.customer_details && obj.customer_details.email) || obj.customer_email || "").toLowerCase();
    if(!email) return;
    const customer = obj.customer || null, sub = obj.subscription || null;
    if(sub) await env.ENTITLEMENTS.put("subemail:" + sub, email);
    if(customer) await env.ENTITLEMENTS.put("custemail:" + customer, email);
    await env.ENTITLEMENTS.put("subof:" + email, JSON.stringify({ sub, customer, status:"trialing", periodEnd:0, updated:Date.now() }));
    return;
  }
  if(evt.type === "customer.subscription.created" || evt.type === "customer.subscription.updated" || evt.type === "customer.subscription.deleted"){
    // Plan subscriptions (Static/Dynamic): keep the entitlement in sync, revoke on cancel.
    if(await env.ENTITLEMENTS.get("plansub:" + obj.id)){
      const st = evt.type === "customer.subscription.deleted" ? "canceled" : (obj.status || "canceled");
      const keep = (st === "active" || st === "trialing" || st === "past_due");   // past_due = grace
      await setPlanStatusBySub(env, obj.id, keep ? (st === "past_due" ? "active" : st) : "canceled");
      return;
    }
    const sub = obj.id, customer = obj.customer || null;
    const status = evt.type === "customer.subscription.deleted" ? "canceled" : (obj.status || "canceled");
    const periodEnd = obj.current_period_end || 0;
    let email = await env.ENTITLEMENTS.get("subemail:" + sub);
    if(!email && customer) email = await env.ENTITLEMENTS.get("custemail:" + customer);
    if(!email) return;
    if(sub) await env.ENTITLEMENTS.put("subemail:" + sub, email);
    if(customer) await env.ENTITLEMENTS.put("custemail:" + customer, email);
    await env.ENTITLEMENTS.put("subof:" + email, JSON.stringify({ sub, customer, status, periodEnd, updated:Date.now() }));
  }
}

// Personal-page id: random bearer token the browser generates (no registration).
function validPid(pid){ return typeof pid === "string" && /^[A-Za-z0-9_-]{16,64}$/.test(pid); }

// Send a personal link to an email via Resend. No-op (returns false) until
// RESEND_API_KEY is set and the from-domain is verified in Resend.
async function sendRecoveryEmail(env, to, link){
  if(!env.RESEND_API_KEY) return false;
  const from = env.RESEND_FROM || "Pacelab <hello@pacelab.me>";
  const html = `<div style="font-family:system-ui,Arial,sans-serif;font-size:15px;line-height:1.5;color:#1a1a1a">`
    + `<p>Here's your personal Pacelab link. Open it on any device to bring back your goal race, plan and progress:</p>`
    + `<p><a href="${link}" style="color:#ff5a1f;font-weight:600">${link}</a></p>`
    + `<p style="color:#666;font-size:13px">Keep it to yourself — anyone who opens it can see your plan.</p></div>`;
  const text = `Here's your personal Pacelab link:\n${link}\n\nOpen it on any device to bring back your goal race, plan and progress. Keep it to yourself — anyone who opens it can see your plan.`;
  try{
    const r = await fetch("https://api.resend.com/emails", {
      method: "POST",
      headers: { Authorization: "Bearer " + env.RESEND_API_KEY, "Content-Type": "application/json" },
      body: JSON.stringify({ from, to: [to], subject: "Your Pacelab link", html, text }),
    });
    return r.ok;
  }catch{ return false; }
}

export default {
  async fetch(request, env) {
    const origin = env.ALLOWED_ORIGIN || DEFAULT_ALLOWED_ORIGIN;
    const cors = {
      "Access-Control-Allow-Origin": origin,
      "Access-Control-Allow-Methods": "POST, OPTIONS",
      "Access-Control-Allow-Headers": "Content-Type",
      "Access-Control-Max-Age": "86400",
    };
    if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: cors });

    const url = new URL(request.url);
    const path = url.pathname;
    const readBody = async () => { try { return await request.json(); } catch { return null; } };

    // ---- Start a subscription checkout (EUR 9.99/mo, 7-day free trial) ----
    if (request.method === "POST" && path.endsWith("/subscribe")) {
      if (!env.STRIPE_SECRET_KEY) return json({ ok:false, reason:"server_unconfigured" }, 500, cors);
      const b = await readBody() || {};
      const price = env.STRIPE_PRICE_PLAN || FALLBACK_PRICE_PLAN;
      const site = env.ALLOWED_ORIGIN || DEFAULT_ALLOWED_ORIGIN;
      const params = new URLSearchParams();
      params.set("mode", "subscription");
      params.set("line_items[0][price]", price);
      params.set("line_items[0][quantity]", "1");
      params.set("subscription_data[trial_period_days]", String(TRIAL_DAYS));
      params.set("allow_promotion_codes", "true");
      params.set("success_url", site + "/?sub=success&session_id={CHECKOUT_SESSION_ID}");
      params.set("cancel_url", site + "/?sub=cancel");
      if (b.email) params.set("customer_email", String(b.email).toLowerCase());
      try {
        const r = await fetch("https://api.stripe.com/v1/checkout/sessions", {
          method: "POST",
          headers: { Authorization: "Bearer " + env.STRIPE_SECRET_KEY, "Content-Type": "application/x-www-form-urlencoded" },
          body: params.toString(),
        });
        const s = await r.json();
        if (!r.ok) return json({ ok:false, reason:"stripe_error", detail: s.error && s.error.message }, 200, cors);
        return json({ ok:true, url: s.url, id: s.id }, 200, cors);
      } catch { return json({ ok:false, reason:"stripe_unreachable" }, 502, cors); }
    }

    // ---- Start checkout for a plan product (race one-time; static/dynamic sub + 14d trial) ----
    if (request.method === "POST" && path.endsWith("/plan/checkout")) {
      if (!env.STRIPE_SECRET_KEY) return json({ ok:false, reason:"server_unconfigured" }, 500, cors);
      const b = await readBody() || {};
      const product = String(b.product || "");
      if (PLAN_PRODUCTS.indexOf(product) < 0) return json({ ok:false, reason:"bad_product" }, 200, cors);
      const price = planPrice(env, product);
      if (!price) return json({ ok:false, reason:"price_unconfigured" }, 200, cors);
      const site = env.ALLOWED_ORIGIN || DEFAULT_ALLOWED_ORIGIN;
      const pid = validPid(b.pid) ? b.pid : "";
      const athleteId = (b.athlete_id && Number(b.athlete_id)) || await athleteIdForPid(env, pid);
      const subMode = product !== "race";
      const params = new URLSearchParams();
      params.set("mode", subMode ? "subscription" : "payment");
      params.set("line_items[0][price]", price);
      params.set("line_items[0][quantity]", "1");
      params.set("metadata[product]", product);
      if (pid) params.set("metadata[pid]", pid);
      if (athleteId) params.set("metadata[athlete_id]", String(athleteId));
      if (subMode) {
        params.set("subscription_data[trial_period_days]", String(PLAN_TRIAL_DAYS));
        params.set("subscription_data[metadata][product]", product);
        if (pid) params.set("subscription_data[metadata][pid]", pid);
        if (athleteId) params.set("subscription_data[metadata][athlete_id]", String(athleteId));
      }
      params.set("success_url", site + "/?plan=success&session_id={CHECKOUT_SESSION_ID}");
      params.set("cancel_url", site + "/?plan=cancel");
      if (b.email) params.set("customer_email", String(b.email).toLowerCase());
      try {
        const r = await fetch("https://api.stripe.com/v1/checkout/sessions", {
          method: "POST",
          headers: { Authorization: "Bearer " + env.STRIPE_SECRET_KEY, "Content-Type": "application/x-www-form-urlencoded" },
          body: params.toString(),
        });
        const s = await r.json();
        if (!r.ok) return json({ ok:false, reason:"stripe_error", detail: s.error && s.error.message }, 200, cors);
        return json({ ok:true, url: s.url, id: s.id }, 200, cors);
      } catch { return json({ ok:false, reason:"stripe_unreachable" }, 502, cors); }
    }

    // ---- Verify a plan checkout on return and persist the entitlement per identity ----
    if (request.method === "POST" && path.endsWith("/plan/verify")) {
      if (!env.STRIPE_SECRET_KEY) return json({ ok:false, reason:"server_unconfigured" }, 500, cors);
      const b = await readBody() || {};
      const sid = b.session_id;
      if (!sid) return json({ ok:false, reason:"no_session" }, 200, cors);
      try {
        const r = await fetch("https://api.stripe.com/v1/checkout/sessions/" + encodeURIComponent(sid) + "?expand%5B%5D=subscription",
          { headers: { Authorization: "Bearer " + env.STRIPE_SECRET_KEY } });
        const s = await r.json();
        if (!r.ok) return json({ ok:false, reason:"stripe_error" }, 200, cors);
        const md = s.metadata || {};
        const product = md.product || "";
        if (PLAN_PRODUCTS.indexOf(product) < 0) return json({ ok:false, reason:"not_a_plan" }, 200, cors);
        const sub = (s.subscription && typeof s.subscription === "object") ? s.subscription : null;
        let status, trialEnds = 0;
        if (product === "race") {
          if (!(s.payment_status === "paid" || s.status === "complete")) return json({ ok:false, reason:"not_paid" }, 200, cors);
          status = "paid";
        } else {
          status = sub ? sub.status : (s.status === "complete" ? "trialing" : "");
          if (["trialing","active"].indexOf(status) < 0) return json({ ok:false, reason:"not_active" }, 200, cors);
          if (sub && sub.trial_end) trialEnds = sub.trial_end * 1000;
        }
        const email = ((s.customer_details && s.customer_details.email) || s.customer_email || "").toLowerCase() || null;
        const pid = validPid(b.pid) ? b.pid : (md.pid || "");
        const athleteId = (md.athlete_id && Number(md.athlete_id)) || await athleteIdForPid(env, pid);
        await grantPlan(env, { product, status, trial_ends_at: trialEnds, sub: sub ? sub.id : (s.subscription || null), customer: s.customer || null, email, athlete_id: athleteId });
        return json({ ok:true, product, status, trial_ends_at: trialEnds }, 200, cors);
      } catch { return json({ ok:false, reason:"stripe_unreachable" }, 502, cors); }
    }

    // ---- Cross-device: which plan does this identity own? (Strava athlete_id, else email) ----
    if (request.method === "POST" && path.endsWith("/plan/status")) {
      if (!env.ENTITLEMENTS) return json({ ok:false }, 200, cors);
      const b = await readBody() || {};
      const pid = validPid(b.pid) ? b.pid : "";
      const athleteId = (b.athlete_id && Number(b.athlete_id)) || await athleteIdForPid(env, pid);
      const email = (b.email && String(b.email).toLowerCase()) || null;
      const rec = await getPlan(env, athleteId, email);
      if (!rec) return json({ ok:false, reason:"none" }, 200, cors);
      return json({ ok:true, product: rec.product, status: rec.status, trial_ends_at: rec.trial_ends_at || 0 }, 200, cors);
    }

    // ---- Adjust today's workout from how the athlete feels (Anthropic Haiku) ----
    // Privacy: the transcript is used only for this call and is never stored.
    if (request.method === "POST" && path.endsWith("/adjust")) {
      if (!env.ANTHROPIC_API_KEY) return json({ ok:false, reason:"server_unconfigured" }, 500, cors);
      const b = await readBody() || {};
      const transcript = String(b.transcript || "").slice(0, 1000).trim();
      const planned = (b.planned && typeof b.planned === "object") ? b.planned : {};
      if (!transcript) return json({ ok:false, reason:"empty" }, 200, cors);
      const sys = "You are a supportive, level-headed running coach for the app Pacelab. Given an athlete's planned workout and how they say they feel today, choose how to adjust TODAY's session. You may ONLY choose one action from: keep, easier, shorter, rest. Bias strongly toward recovery whenever they feel unwell, low-energy, sore, ill, stressed, poorly slept, or are managing menstrual symptoms - these are normal, valid reasons to reduce load. NEVER make the session harder than planned. If they describe real pain, injury, dizziness, or illness beyond ordinary fatigue, choose rest and gently suggest easing off and checking with a professional if it persists, but do not diagnose or give medical advice. If they clearly feel great and ready, you may keep the session. Reply with ONLY a JSON object, no prose, no markdown fences: {\"action\":\"keep|easier|shorter|rest\",\"message\":\"one or two warm, brief sentences spoken directly to the athlete\"}.";
      const user = "Planned workout today: " + (planned.title || "a session") + " - " + (planned.detail || "") + "\nAthlete says: \"" + transcript + "\"";
      try {
        const r = await fetch("https://api.anthropic.com/v1/messages", {
          method: "POST",
          headers: { "x-api-key": env.ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01", "content-type": "application/json" },
          body: JSON.stringify({ model: env.ANTHROPIC_MODEL || "claude-haiku-4-5-20251001", max_tokens: 300, system: sys, messages: [{ role: "user", content: user }] }),
        });
        const d = await r.json();
        if (!r.ok) return json({ ok:false, reason:"model_error", detail: (d.error && d.error.message) || "" }, 200, cors);
        let text = ""; (d.content || []).forEach(c => { if (c.type === "text") text += c.text; });
        text = text.replace(/```json|```/g, "").trim();
        let parsed = {}; try { parsed = JSON.parse(text); } catch {}
        const allowed = ["keep", "easier", "shorter", "rest"];
        const action = allowed.indexOf(parsed.action) >= 0 ? parsed.action : "easier";
        const message = String(parsed.message || "Adjusted for how you're feeling today.").slice(0, 400);
        return json({ ok:true, action, message }, 200, cors);
      } catch { return json({ ok:false, reason:"model_unreachable" }, 502, cors); }
    }

    // ---- Stripe webhook: keep subscription entitlement current ----
    if (request.method === "POST" && path.endsWith("/stripe-webhook")) {
      const sig = request.headers.get("Stripe-Signature") || "";
      const raw = await request.text();
      const okSig = await verifyStripeSignature(raw, sig, env.STRIPE_WEBHOOK_SECRET);
      if (!okSig) return new Response("bad signature", { status: 400 });
      let evt; try { evt = JSON.parse(raw); } catch { return new Response("bad json", { status: 400 }); }
      try { await handleStripeEvent(evt, env); } catch {}
      return new Response("ok", { status: 200 });
    }

    // ---- Course data: free always, paid only with a valid pass ----
    if (request.method === "POST" && path.endsWith("/data")) {
      const b = await readBody() || {};
      const payload = b.pass ? await verifyPass(env.TOKEN_SECRET, b.pass) : null;
      return json(buildDataResponse(payload), 200, cors);
    }

    // ---- Race-day effective temperature (Open-Meteo, cached) ----
    // Public (weather is not paid content). For a single specific race day:
    // upcoming within 2 weeks -> live forecast; otherwise the most recent
    // edition's actual archived weather. Cached per course+date in KV.
    if (request.method === "POST" && path.endsWith("/conditions")) {
      const b = await readBody() || {};
      const name = (b.name || "").trim();
      const c = COORDS[name];
      if (!c) return json({ ok:false, reason:"unknown_course", name }, 200, cors);
      const now = new Date();
      const target = resolveRaceDate(c, now);
      const key = `cond:v4:${name}:${target.weatherDate}:${target.displayDate}`;
      if (env.ENTITLEMENTS) {
        try { const hit = await env.ENTITLEMENTS.get(key); if (hit) return json(JSON.parse(hit), 200, cors); } catch {}
      }
      let w = null;
      try { w = await fetchRaceDayConditions(c, now); } catch { w = null; }
      if (!w) return json({ ok:false, reason:"weather_unavailable", name, date: target.weatherDate, displayDate: target.displayDate, mode: target.weatherMode }, 200, cors);
      const effTempC = effectiveRunningTemp(w);
      const out = {
        ok: true, name, date: w.weatherDate, displayDate: w.displayDate, mode: w.mode,
        airTempC: round1(w.airTempC), rh: Math.round(w.rh),
        windKmh: round1(w.windKmh), solarWm2: Math.round(w.solarWm2),
        effTempC: round1(effTempC), samples: w.samples,
        summary: conditionsSummary(w)
      };
      if (env.ENTITLEMENTS) {
        // Forecasts refresh as race day nears (6h); historical days are fixed (30d).
        const ttl = w.mode === "forecast" ? 60 * 60 * 6 : 60 * 60 * 24 * 30;
        try { await env.ENTITLEMENTS.put(key, JSON.stringify(out), { expirationTtl: ttl }); } catch {}
      }
      return json(out, 200, cors);
    }

    // ---- Verify a paid Stripe session (one-time OR subscription), return a pass ----
    if (request.method === "POST" && path.endsWith("/verify")) {
      const b = await readBody() || {};
      const sid = b.session_id;
      if (!sid) return json({ ok:false, reason:"missing_session" }, 400, cors);
      if (!env.STRIPE_SECRET_KEY) return json({ ok:false, reason:"server_unconfigured" }, 500, cors);
      let s;
      try {
        const r = await fetch("https://api.stripe.com/v1/checkout/sessions/" + encodeURIComponent(sid) + "?expand%5B%5D=subscription",
          { headers: { Authorization: "Bearer " + env.STRIPE_SECRET_KEY } });
        s = await r.json();
        if (!r.ok) return json({ ok:false, reason:"stripe_error" }, 200, cors);
      } catch { return json({ ok:false, reason:"stripe_unreachable" }, 502, cors); }

      const email = ((s.customer_details && s.customer_details.email) || s.customer_email || "").toLowerCase();

      if (s.mode === "subscription") {
        if (s.status !== "complete") return json({ ok:false, reason:"not_complete" }, 200, cors);
        const subObj  = (s.subscription && typeof s.subscription === "object") ? s.subscription : null;
        const sub     = subObj ? subObj.id : (s.subscription || null);
        const status  = subObj ? subObj.status : "trialing";
        const periodEnd = subObj ? (subObj.current_period_end || 0) : 0;
        const customer = (s.customer && (s.customer.id || s.customer)) || null;
        if (email && env.ENTITLEMENTS) {
          if (sub) await env.ENTITLEMENTS.put("subemail:" + sub, email);
          if (customer) await env.ENTITLEMENTS.put("custemail:" + customer, email);
          await env.ENTITLEMENTS.put("subof:" + email, JSON.stringify({ sub, customer, status, periodEnd, updated: Date.now() }));
        }
        const issued = await issuePass(env, email);
        return json({ ok:true, email, plan:true, status, unlocked: grantedNames(issued.unlocked), pass: issued.pass }, 200, cors);
      }

      // one-time purchase (unchanged behavior)
      const paid = s.payment_status === "paid" || s.status === "complete";
      if (!paid) return json({ ok:false, reason:"not_paid" }, 200, cors);
      const grant = entitlementFromSession(s);
      if (email && env.ENTITLEMENTS) {
        const prevRaw = await env.ENTITLEMENTS.get("ent:" + email);
        const prev = prevRaw ? JSON.parse(prevRaw) : null;
        let merged = grant;
        if ((prev && prev.unlocked === "all") || grant === "all") merged = "all";
        else merged = Array.from(new Set([...(prev && Array.isArray(prev.unlocked) ? prev.unlocked : []), ...grant]));
        await env.ENTITLEMENTS.put("ent:" + email, JSON.stringify({ unlocked: merged, updated: Date.now() }));
      }
      const issued = await issuePass(env, email);
      return json({ ok:true, email, unlocked: grantedNames(issued.unlocked), pass: issued.pass }, 200, cors);
    }

    // ---- Restore entitlement by email (one-time + current subscription) ----
    if (request.method === "POST" && path.endsWith("/restore")) {
      const b = await readBody() || {};
      const email = (b.email || "").toLowerCase();
      if (!email || !env.ENTITLEMENTS) return json({ ok:false }, 200, cors);
      const issued = await issuePass(env, email);
      const names = grantedNames(issued.unlocked);
      if (names.length === 0) return json({ ok:false }, 200, cors);
      return json({ ok:true, unlocked: names, pass: issued.pass }, 200, cors);
    }

    // ---- Load a personal page: saved state + (if linked) current entitlement ----
    if (request.method === "POST" && path.endsWith("/page/load")) {
      if (!env.ENTITLEMENTS) return json({ ok:false, reason:"server_unconfigured" }, 200, cors);
      const b = await readBody() || {};
      const pid = b.pid;
      if (!validPid(pid)) return json({ ok:false, reason:"bad_pid" }, 400, cors);
      const raw = await env.ENTITLEMENTS.get("page:" + pid);
      const rec = raw ? (JSON.parse(raw) || {}) : null;
      const out = { ok:true, state: (rec && rec.state) || null, email: (rec && rec.email) || null };
      // If this page is linked to an email, hand back current entitlement too, so the
      // paid content unlocks on whatever device opened the link.
      if (rec && rec.email) {
        const issued = await issuePass(env, rec.email);
        const names = grantedNames(issued.unlocked);
        if (names.length) { out.unlocked = names; out.pass = issued.pass; }
      }
      return json(out, 200, cors);
    }

    // ---- Save a personal page's state (and optionally link an email) ----
    if (request.method === "POST" && path.endsWith("/page/save")) {
      if (!env.ENTITLEMENTS) return json({ ok:false, reason:"server_unconfigured" }, 200, cors);
      const b = await readBody() || {};
      const pid = b.pid;
      if (!validPid(pid)) return json({ ok:false, reason:"bad_pid" }, 400, cors);
      const stateStr = JSON.stringify(b.state || {});
      if (stateStr.length > 64 * 1024) return json({ ok:false, reason:"too_large" }, 413, cors);
      const raw = await env.ENTITLEMENTS.get("page:" + pid);
      const rec = raw ? (JSON.parse(raw) || {}) : {};
      rec.state = b.state || {};
      rec.updated = Date.now();
      if (b.email && typeof b.email === "string" && b.email.indexOf("@") > 0) {
        rec.email = b.email.toLowerCase();
        await env.ENTITLEMENTS.put("pidof:" + rec.email, pid); // lets email recovery find this page
      }
      await env.ENTITLEMENTS.put("page:" + pid, JSON.stringify(rec));
      return json({ ok:true }, 200, cors);
    }

    // ---- Email a personal link (proactive backup + lost-link recovery) ----
    // {email, pid?}. If the email is already linked to a page, we send THAT link
    // (recovery; we never overwrite an existing mapping). Otherwise we link the
    // supplied page to the email and send it (first-time backup). Always returns
    // ok so it can't be used to discover which emails exist.
    if (request.method === "POST" && path.endsWith("/page/email")) {
      if (!env.ENTITLEMENTS) return json({ ok:true }, 200, cors);
      const b = await readBody() || {};
      const email = (b.email || "").toString().trim().toLowerCase();
      if (email.indexOf("@") <= 0) return json({ ok:true }, 200, cors);
      let targetPid = null;
      const existing = await env.ENTITLEMENTS.get("pidof:" + email);
      if (validPid(existing)) {
        targetPid = existing;                       // already linked -> recover, don't overwrite
      } else if (validPid(b.pid)) {
        targetPid = b.pid;                          // first time -> link this page to the email
        const raw = await env.ENTITLEMENTS.get("page:" + targetPid);
        const rec = raw ? (JSON.parse(raw) || {}) : {};
        rec.email = email; rec.updated = Date.now();
        await env.ENTITLEMENTS.put("page:" + targetPid, JSON.stringify(rec));
        await env.ENTITLEMENTS.put("pidof:" + email, targetPid);
      }
      if (targetPid) {
        const site = env.ALLOWED_ORIGIN || DEFAULT_ALLOWED_ORIGIN;
        try { await sendRecoveryEmail(env, email, site + "/plans.html?p=" + targetPid); } catch {}
      }
      return json({ ok:true }, 200, cors);
    }

    // ---- Comp/test unlock: validates the code, returns an all-access pass ----
    if (request.method === "POST" && path.endsWith("/unlock")) {
      const b = await readBody() || {};
      const ok = !!(b.code && env.UNLOCK_CODE && b.code === env.UNLOCK_CODE);
      if (!ok) return json({ ok:false }, 200, cors);
      const pass = await signPass(env.TOKEN_SECRET, { unlocked:"all", email:"comp", iat: Date.now() });
      return json({ ok:true, unlocked: PAID_NAMES.slice(), pass }, 200, cors);
    }

    // ---- Strava OAuth exchange -> estimate (unchanged) ----
    if (request.method === "POST" && path.endsWith("/exchange")) {
      const body = await readBody();
      const code = body && body.code;
      const pid = body && body.pid;
      if (!code) return json({ error: "Missing code" }, 400, cors);
      let token, refreshToken = "", athleteId = 0;
      try {
        const tokenRes = await fetch("https://www.strava.com/oauth/token", {
          method: "POST", headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ client_id: env.STRAVA_CLIENT_ID, client_secret: env.STRAVA_CLIENT_SECRET, code, grant_type: "authorization_code" }),
        });
        const tokenData = await tokenRes.json();
        if (!tokenRes.ok || !tokenData.access_token) return json({ error: "Strava auth failed", detail: tokenData }, 502, cors);
        token = tokenData.access_token;
        refreshToken = tokenData.refresh_token || "";
        athleteId = (tokenData.athlete && tokenData.athlete.id) || 0;
      } catch (e) { return json({ error: "Token exchange error" }, 502, cors); }

      // Store the refresh token (keyed to the private page id) so we can check in on
      // their training later without asking them to reconnect. Also link the Strava
      // athlete_id so the same account unlocks across the user's devices, and return
      // that account's current entitlement.
      let account = { unlocked: [], pass: null };
      if (pid && refreshToken && env.ENTITLEMENTS) {
        try { account = await linkStrava(env, pid, athleteId, refreshToken); } catch (e) {}
      }
      // Funnel event: emitted server-side so the athlete_id is only recorded on a
      // genuinely successful connection (and can't be spoofed from the client).
      try { await logEvent(env, { name: "strava_oauth_success", pid: pid || null, path: "/exchange", athlete_id: athleteId || 0 }); } catch (e) {}

      let activities = [];
      try {
        for (let page = 1; page <= 2; page++) {
          const res = await fetch(`https://www.strava.com/api/v3/athlete/activities?per_page=200&page=${page}`, { headers: { Authorization: `Bearer ${token}` } });
          if (!res.ok) break;
          const chunk = await res.json();
          if (!Array.isArray(chunk) || chunk.length === 0) break;
          activities = activities.concat(chunk);
          if (chunk.length < 200) break;
        }
      } catch (e) { return json({ error: "Could not read activities" }, 502, cors); }

      const result = estimateMarathon(activities);
      if (!result) return json({ error: "not_enough_data", message: "We couldn't find enough runs to estimate a time yet.", account }, 200, cors);
      return json({ ...result, account }, 200, cors);
    }

    // ---- Recent activity for the training check-in (refresh token, pull last ~16 days) ----
    if (request.method === "POST" && path.endsWith("/strava/recent")) {
      if (!env.ENTITLEMENTS) return json({ ok:false, reason:"server_unconfigured" }, 200, cors);
      const b = await readBody() || {};
      const pid = b.pid;
      if (!pid) return json({ ok:false, reason:"no_pid" }, 200, cors);
      const raw = await env.ENTITLEMENTS.get("strava:" + pid);
      if (!raw) return json({ ok:false, reason:"not_connected" }, 200, cors);
      let rec; try { rec = JSON.parse(raw); } catch (e) { return json({ ok:false, reason:"not_connected" }, 200, cors); }
      let access;
      try {
        const rr = await fetch("https://www.strava.com/oauth/token", {
          method: "POST", headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ client_id: env.STRAVA_CLIENT_ID, client_secret: env.STRAVA_CLIENT_SECRET, grant_type: "refresh_token", refresh_token: rec.refresh_token }),
        });
        const rd = await rr.json();
        if (!rr.ok || !rd.access_token) return json({ ok:false, reason:"reauth" }, 200, cors);
        access = rd.access_token;
        if (rd.refresh_token && rd.refresh_token !== rec.refresh_token) {
          rec.refresh_token = rd.refresh_token; rec.at = Date.now();
          try { await env.ENTITLEMENTS.put("strava:" + pid, JSON.stringify(rec)); } catch (e) {}
        }
      } catch (e) { return json({ ok:false, reason:"reauth" }, 200, cors); }
      const afterEpoch = Math.floor((Date.now() - 16 * 24 * 3600 * 1000) / 1000);
      let acts = [];
      try {
        const res = await fetch(`https://www.strava.com/api/v3/athlete/activities?after=${afterEpoch}&per_page=60`, { headers: { Authorization: `Bearer ${access}` } });
        if (res.ok) { const chunk = await res.json(); if (Array.isArray(chunk)) acts = chunk; }
        else return json({ ok:false, reason:"fetch_failed" }, 200, cors);
      } catch (e) { return json({ ok:false, reason:"fetch_failed" }, 200, cors); }
      return json(summarizeRecent(acts), 200, cors);
    }

    // ---- Cross-device account for a connected athlete (unlock the same content
    //      on a second device). {pid} or {athlete_id}. Returns {unlocked, pass}. ----
    if (request.method === "POST" && path.endsWith("/strava/account")) {
      if (!env.ENTITLEMENTS) return json({ ok:false, reason:"server_unconfigured" }, 200, cors);
      const b = await readBody() || {};
      let athleteId = b.athlete_id || 0;
      if (!athleteId && validPid(b.pid)) {
        try { const s = await env.ENTITLEMENTS.get("strava:" + b.pid); if (s) athleteId = (JSON.parse(s)||{}).athlete_id || 0; } catch (e) {}
      }
      if (!athleteId) return json({ ok:false, reason:"unknown" }, 200, cors);
      const acc = await accountForAthlete(env, athleteId);
      return json({ ok:true, athlete_id: athleteId, unlocked: acc.unlocked, pass: acc.pass }, 200, cors);
    }

    // ---- Forget the stored Strava token (called when the user disconnects) ----
    if (request.method === "POST" && path.endsWith("/strava/disconnect")) {
      if (!env.ENTITLEMENTS) return json({ ok:true }, 200, cors);
      const b = await readBody() || {};
      if (b.pid) { try { await env.ENTITLEMENTS.delete("strava:" + b.pid); } catch (e) {} }
      return json({ ok:true }, 200, cors);
    }

    // ---- Funnel analytics beacon (anonymous). The client may only send user-side
    //      events; strava_oauth_success is emitted server-side in /exchange. We never
    //      accept athlete_id / tokens / email here. ----
    if (request.method === "POST" && path.endsWith("/ev")) {
      const b = await readBody() || {};
      const name = String(b.name || "");
      const CLIENT_EVENTS = ["page_open","marathon_selected","connect_strava_clicked","result_viewed","checkout_started","purchase_completed"];
      if (!CLIENT_EVENTS.includes(name)) return json({ ok:false, reason:"bad_event" }, 200, cors);
      await logEvent(env, {
        name,
        pid: validPid(b.pid) ? b.pid : null,
        path: typeof b.path === "string" ? b.path : null,
        marathon: typeof b.marathon === "string" ? b.marathon : null,
        // athlete_id intentionally ignored from client input
      });
      return json({ ok:true }, 200, cors);
    }

    return json({ error: "Not found" }, 404, cors);
  },

  // Cron Trigger entrypoint: revoke + remove Strava connections that never
  // converted within 24h. Configure the schedule in wrangler.toml, e.g.:
  //   [triggers]
  //   crons = ["0 * * * *"]     # hourly
  async scheduled(event, env, ctx) {
    ctx.waitUntil((async () => {
      const t0 = Date.now();
      const result = await cleanupUnconverted(env);
      // Visible in `wrangler tail`: confirms the cron fired and what it did.
      console.log("cron cleanupUnconverted", JSON.stringify({ cron: event && event.cron, ...result, ms: Date.now() - t0 }));
    })());
  },
};

// --- Daniels VDOT (validated against Daniels' Running Formula tables) ---
function _vo2(v){ return -4.60 + 0.182258*v + 0.000104*v*v; }
function _pctMax(t){ return 0.8 + 0.1894393*Math.exp(-0.012778*t) + 0.2989558*Math.exp(-0.1932605*t); }
function vdotFromPerf(distM, timeSec){ const t=timeSec/60, v=distM/t; return _vo2(v)/_pctMax(t); }
function vdotRaceSec(vdot, distM){ let lo=distM/600, hi=distM/50; for(let i=0;i<80;i++){ const t=(lo+hi)/2, est=_vo2(distM/t)/_pctMax(t); if(est>vdot) lo=t; else hi=t; } return ((lo+hi)/2)*60; }

function estimateMarathon(activities) {
  const now = Date.now();
  const oneYearAgo = now - 365 * 24 * 3600 * 1000;
  const runs = (activities || []).filter((a) => a && a.type === "Run" && a.distance > 0 && a.moving_time > 0 && new Date(a.start_date).getTime() >= oneYearAgo);
  if (runs.length === 0) return null;
  const totalKm = runs.reduce((s, r) => s + r.distance / 1000, 0);
  const spanWeeks = Math.max(1, (now - new Date(runs[runs.length - 1].start_date).getTime()) / (7 * 24 * 3600 * 1000));
  const weeklyKm = +(totalKm / spanWeeks).toFixed(1);
  let predictors = runs.filter((r) => r.distance >= 10000);
  if (predictors.length < 3) predictors = runs.filter((r) => r.distance >= 5000);
  if (predictors.length === 0) return null;
  const projected = predictors.map((r) => ({ seconds: r.moving_time * Math.pow(MARATHON_M / r.distance, RIEGEL_EXP), distanceKm: +(r.distance / 1000).toFixed(1), timeSeconds: r.moving_time, date: r.start_date })).sort((a, b) => a.seconds - b.seconds);
  const topN = projected.slice(0, Math.min(3, projected.length));
  const estimateSeconds = Math.round(topN.reduce((s, p) => s + p.seconds, 0) / topN.length);
  const longRuns = runs.filter((r) => r.distance >= 18000).length;
  let confidence = "low";
  if (predictors.length >= 8 && longRuns >= 3 && weeklyKm >= 30) confidence = "high";
  else if (predictors.length >= 4 && weeklyKm >= 15) confidence = "medium";
  const basis = projected[0];
  // Daniels VDOT from the best recent efforts (avg of top 3 predictor runs), and the
  // realistic best marathon that VDOT implies. This is their current-fitness ceiling.
  let vdot = 0;
  try {
    const vs = predictors.map((r) => vdotFromPerf(r.distance, r.moving_time)).filter((v) => v >= 20 && v <= 85).sort((a, b) => b - a);
    if (vs.length) { const n = Math.min(3, vs.length); vdot = vs.slice(0, n).reduce((s, v) => s + v, 0) / n; }
  } catch (e) {}
  vdot = Math.round(vdot * 10) / 10;
  const vdotMarathonSeconds = vdot ? Math.round(vdotRaceSec(vdot, MARATHON_M)) : estimateSeconds;
  const last = runs[0];
  const lastActivity = last ? { date: last.start_date, distanceKm: +(last.distance / 1000).toFixed(1), movingTimeSeconds: last.moving_time, name: String(last.name || "").slice(0, 80), type: last.type } : null;
  return { estimateSeconds, estimateHMS: toHMS(estimateSeconds), confidence, runsAnalyzed: runs.length, predictiveRuns: predictors.length, longRuns, weeklyKm, vdot, vdotMarathonSeconds, vdotMarathonHMS: toHMS(vdotMarathonSeconds), lastActivity, basis: { distanceKm: basis.distanceKm, timeSeconds: basis.timeSeconds, timeHMS: toHMS(basis.timeSeconds), date: basis.date } };
}
function toHMS(totalSeconds) { const s = Math.max(0, Math.round(totalSeconds)); const h = Math.floor(s / 3600); const m = Math.floor((s % 3600) / 60); const sec = s % 60; const pad = (n) => String(n).padStart(2, "0"); return `${h}:${pad(m)}:${pad(sec)}`; }
function json(obj, status, cors) { return new Response(JSON.stringify(obj), { status, headers: { "Content-Type": "application/json", ...cors } }); }

// Turn raw Strava activities into a compact summary: runs (with avg pace) + other
// sports (football/gym/etc.) so the coach can react and account for cross-training.
function summarizeRecent(acts) {
  const runs = [], other = [];
  (acts || []).forEach((a) => {
    if (!a) return;
    const t = a.type || a.sport_type || "";
    const dateISO = String(a.start_date_local || a.start_date || "").slice(0, 10);
    if (t === "Run" || t === "TrailRun" || t === "VirtualRun") {
      const km = (a.distance || 0) / 1000, sec = a.moving_time || 0;
      runs.push({ date: dateISO, distanceKm: +km.toFixed(2), movingSec: sec, avgPaceSec: km > 0 ? Math.round(sec / km) : 0, elevGain: Math.round(a.total_elevation_gain || 0), name: String(a.name || "").slice(0, 80) });
    } else if (t) {
      other.push({ date: dateISO, type: t, movingSec: a.moving_time || 0, name: String(a.name || "").slice(0, 80) });
    }
  });
  const byDateDesc = (x, y) => (x.date < y.date ? 1 : x.date > y.date ? -1 : 0);
  runs.sort(byDateDesc); other.sort(byDateDesc);
  return { ok: true, runs, other, at: Date.now() };
}

